INSERT INTO `email_templates` (`id`, `name`, `slug`, `subject`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'WELCOME', 'welcome', 'WELCOME [NAME]!', 'WELCOME [NAME]!\n\nYou have successfully registered on Shortlet app.', 0, '2020-07-03 08:32:38', '2022-11-21 09:30:30', NULL),
(5, 'FORGOT YOUR PASSWORD!', 'forgot_password', 'test', 'There was a request to change your password!\n\nYour forgot password OTP is: [OTP]', 0, '2022-04-19 05:36:04', '2022-12-06 13:15:37', NULL),
(12, 'Check-In Form', 'checking_form', 'Booking request [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\r\n									Thank you for your booking request. These are the booking details..', 1, '2022-04-19 05:36:04', '2023-03-28 11:47:03', NULL),
(13, 'Contract Expire', 'contract_expire', 'Contract Expire', 'Contract Expire', 1, '2022-04-19 05:36:04', '2022-10-28 13:18:45', NULL),
(14, 'Welcome', 'host_welcome', 'Host Welcome', 'WELCOME [NAME]!\r\n\r\nYou have successfully registered on Shortlet app. Your login url is [URL], username: [USERNAME] and password: [PASSWORD]\r\n\r\nThank you,\r\nTeam Shortlet Rental', 1, '2023-01-06 09:50:57', NULL, NULL),
(15, 'Booking Reservation', 'booking_reservation', 'Booking Reservation', 'Your booking reservation request has been approved. Please payment your booking amount - ([TOTAL_AMOUNT]!). Please click on the link [CHECKOUT]! to pay your booking amount.', 1, '2023-01-09 12:34:00', NULL, NULL),
(16, 'Sub Admin Welcome', 'sub_admin_welcome', 'Sub Admin Welcome', 'WELCOME [NAME]!\r\n\r\nYou have successfully registered on Shortlet app. Your login url is [URL], username: [USERNAME] and password: [PASSWORD]\r\n\r\nThank you,\r\nTeam Shortlet Rental', 1, '2023-02-28 11:27:42', '2023-02-28 06:02:54', NULL),
(17, 'Appointment Cancel', 'appointment-cancel', 'Appointment Cancel', 'Dear [NAME]!\r\n\r\nThank You for Schedule Appointment. But we are not able to confirm your Schedule Appointment. So we are cancel your Appointment. Please schedule another day. \r\n\r\nThank you,\r\nTeam Shortlet Rental', 1, '2023-03-22 06:24:12', '2023-03-22 06:31:09', NULL),
(19, 'Booking Rating & Review completed', 'review-completed', 'Booking Rating & Review completed', 'Dear Sir/Madame,\r\nwe inform you that there is a new review in the rating system. Before it appears on the website, you need to validate it.', 1, '2023-03-27 13:17:59', '2023-03-27 13:18:42', NULL),
(20, 'booking completed', 'booking-completed', 'Booking Completed', 'WELCOME [NAME]!\r\n\r\nYou have successfully registered on Shortlet app. Your login url is [URL], username: [USERNAME] and password: [PASSWORD]\r\n\r\nThank you,\r\nTeam Shortlet Rental', 0, '2023-03-28 11:54:16', '2023-03-28 11:56:18', NULL),
(21, '', 'Booking-confirmation-Apartment\r\n', NULL, NULL, 0, '2023-03-30 04:50:37', NULL, NULL),
(22, 'Your booking has been ongoing!', 'Ongoing-Booking', 'Booking Ongoing', 'We remind you that your booking in onging. we are process you booking for next process', 0, '2023-03-30 04:50:44', '2023-03-30 04:51:40', NULL),
(23, 'Your booking has been completed!', 'Completed-Booking', 'Booking Completed\r\n\r\n', 'Dear Sir/Madam, <br> we inform you that your booking No. [Booking_Id] has been completed.', 0, '2023-03-30 04:50:54', '2023-03-30 04:52:01', NULL),
(24, 'Your booking has been cancelled!', 'Cancelled-Booking', 'Booking Cancellation', '\r\nWe are sorry on this occasion you have not stayed with us and we remind you that your cancellation is in accordance with cancellation policy agreed:', 0, '2023-03-30 04:51:03', '2023-03-30 04:52:18', NULL),
(25, 'Your booking is yet to be confirmed!', 'Booking-confirmed-payment-pending', 'booking confirmed & payment panding', 'We remind you that the payment must be made in order to confirm your booking.', 0, '2023-03-30 04:51:13', '2023-03-30 04:52:43', NULL),
(26, 'Reserve Booking request', 'reserve-book', 'Reserve Booking request [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\r\n									Thank you for your reserve booking request. These are the booking details..', 0, '2023-03-30 11:37:28', '2023-03-30 11:38:45', NULL),
(27, 'Your Booking Reservation has been Deny\r\n', 'Booking-Reservation-deny', 'Booking Reservation Deny', 'Your booking reservation request has been deny.\r\n', 0, '2023-03-30 11:39:43', '2023-03-30 11:40:05', NULL);
INSERT INTO `email_template_lang` (`id`, `email_id`, `name`, `subject`, `description`, `footer`, `lang`, `created_at`, `updated_at`) VALUES
(1, 1, 'WELCOME [NAME]!', 'Welcome to Shortlet Rentals platform', 'WELCOME [NAME]!\r\n\r\nYou have successfully registered on Shortlet Rental platform.', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2021-01-19 01:30:25', '2023-03-06 00:07:32'),
(31, 12, 'Check-In Form', 'Booking request [PROPERTY_NAME]', 'Dear Sir/Madame,<br>\r\n									Thank you for your booking request. These are the booking details..', 'Copyright Â© 2023 ShortletRental. All rights reserved.', 'en', '2021-01-19 03:52:46', '2023-03-06 00:15:35'),
(32, 13, 'Contract Expire', 'Host Welcome', 'Contract Expire', 'Copyright Â© 2023 ShortletRental. All rights reserved.', 'en', '2021-01-19 03:52:46', '2023-02-27 01:06:09'),
(33, 14, 'New Host Registration:', 'Host Registration: Welcome to Shortletrentals.com', 'WELCOME [NAME]!\r\n\r\nThank you for joining Shortletrentals.com\r\n\r\nYou are now part of Nigeria\'s largest accommodation platform- and we are glad you are here.\r\n\r\nwe know you probably have some questions, so here are a few resources to help you get started:\r\n\r\nGetting Started:\r\n\r\nAccess your account: Your account is where you can continue registering your property, add new properties or make any changes like price per night, bookable dates  and more.\r\n\r\nYour login url is [URL], username: [USERNAME] and password: [PASSWORD]\r\n\r\nStill have some questions?\r\n\r\nthe help center helps you with everything- from getting started with our new comers guide to optimizing your presence on the site and getting the most out of shortletrentals.com. you can also find the answers to our most frequently asked questions about being a host on shortletrentals.com\r\n\r\nhelp center link https://zea-virtual-events.com/shortletrental/blog/\r\n\r\nThank you,\r\n\r\n Shortlet Rentals Team', 'Copyright Â© 2023 ShortletRental. All rights reserved.', 'en', '2023-01-06 09:53:00', '2023-03-05 20:55:58'),
(34, 15, 'Booking Reservation', 'Booking Reservation request for - [PROPERTY_NAME], [CITY], [AREA] has been approved', 'Dear [NAME]\r\n\r\nyour reservation request to book  [PROPERTY_NAME] [CITY], [AREA] has been approved.\r\n\r\n Booking Information: \r\n\r\nINSERT IMAGE OF APARTMENT \r\n\r\nCheck in and check out date, \r\n\r\nPrice breakdown- \r\n\r\nprice by night X no of nights, \r\nOptional services X amount paid for ,  \r\nCAUTION FEE\r\nTotal  booking amount - ([TOTAL_AMOUNT]!).\r\n\r\n Please click on the link [CHECKOUT]! to pay your booking amount VIA credit card or if you choose to pay via bank transfer- make a bank transfer deposit to Shortlet Rentals bank account-Zenith Bank- Account number- 1214818652. Send payment slip via Whatsapp to +234 912 287 7657. Thank you.', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-01-09 12:35:15', '2023-03-06 00:28:47'),
(35, 16, 'Sub Admin Platform Users', 'Welcome to Shortlet Rentals Platform', 'WELCOME [NAME]!\r\n\r\nYour account has  been successfully created on the Shortlet Rentals platform. Your login url is [URL], username: [USERNAME] and password: [PASSWORD]\r\n\r\nKindly change your password once you successfully log in . \r\n\r\nTo change your password, click on your name in the top right corner and click on profile.\r\n\r\nWelcome to Shortlet Rentals. We look forward to an amazing time of creating magic together\r\n\r\nThank you,\r\nShortlet Rental Team', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-02-28 11:27:47', '2023-03-05 20:15:57'),
(36, 17, 'Appointment Cancel', 'Appointment Cancel', 'Dear [NAME]!\r\n\r\nThank You for Schedule Appointment. But we are not able to confirm your Schedule Appointment. So we are cancel your Appointment. Please schedule another day. \r\n\r\nThank you,\r\nTeam Shortlet Rental', 'Copyright Â© 2023 Shortlet Rentals. All rights reserved.', 'en', '2023-03-22 06:30:24', NULL),
